begin; alter function public.imaket_review_creator(uuid,text) set schema imaket_private; alter function public.imaket_check_coupon(text,text) set schema imaket_private; grant usage on schema imaket_private to anon; create function public.imaket_review_creator(creator_uuid uuid,decision text) returns void language sql security invoker set search_path='' as $$select imaket_private.imaket_review_creator(creator_uuid,decision)$$; revoke all on function public.imaket_review_creator(uuid,text) from public,anon; grant execute on function public.imaket_review_creator(uuid,text) to authenticated; create function public.imaket_check_coupon(coupon_code text,store_slug text) returns table(percent_off integer) language sql stable security invoker set search_path='' as $$select * from imaket_private.imaket_check_coupon(coupon_code,store_slug)$$; revoke all on function public.imaket_check_coupon(text,text) from public; grant execute on function public.imaket_check_coupon(text,text) to anon,authenticated; commit;
